  "Cancel": "\u0625\u0644\u063A\u0627\u0621",
  "Saving profile...": "\u062C\u0627\u0631\u064D \u062D\u0641\u0638 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0634\u062E\u0635\u064A...",
