  "Your name": "\u0627\u0633\u0645\u0643",
  "Email Address": "\u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A",
  "Bio": "\u0646\u0628\u0630\u0629",
  "Tell us about yourself...": "\u0623\u062E\u0628\u0631\u0646\u0627 \u0639\u0646 \u0646\u0641\u0633\u0643...",
