  "Tayar Coding Assistance": "\u0645\u0633\u0627\u0639\u062F\u0629 Tayar \u0627\u0644\u0628\u0631\u0645\u062C\u064A\u0629",
  "UI Registry": "\u0633\u062C\u0644 \u0648\u0627\u062C\u0647\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645",
  "Reading active project": "\u062C\u0627\u0631\u064D \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0646\u0634\u0637",
  "Project context unavailable": "\u0633\u064A\u0627\u0642 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u063A\u064A\u0631 \u0645\u062A\u0627\u062D",
  "Loading open-source registries": "\u062C\u0627\u0631\u064D \u062A\u062D\u0645\u064A\u0644 \u0633\u062C\u0644\u0627\u062A \u0627\u0644\u0645\u0635\u0627\u062F\u0631 \u0627\u0644\u0645\u0641\u062A\u0648\u062D\u0629",
  "Target project": "\u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0645\u0633\u062A\u0647\u062F\u0641",
