  "Clear private session files": "\u0645\u0633\u062D \u0645\u0644\u0641\u0627\u062A \u0627\u0644\u062C\u0644\u0633\u0629 \u0627\u0644\u062E\u0627\u0635\u0629",
  "Full Feature Generator": "\u0645\u0648\u0644\u0651\u062F \u0627\u0644\u0645\u064A\u0632\u0627\u062A \u0627\u0644\u0643\u0627\u0645\u0644",
